// src/core.ts
function printBlockOutputHtml(output) {
  if ("html" in output) return `<div class="matrx-print-block">${output.html}</div>`;
  if ("image" in output) {
    const { src, alt, caption } = output.image;
    return `<figure class="matrx-print-block matrx-print-image"><img src="${escapeHtml(src)}" alt="${escapeHtml(
      alt ?? "Picture"
    )}" style="max-width:100%;height:auto">${caption ? `<figcaption>${escapeHtml(caption)}</figcaption>` : ""}</figure>`;
  }
  return `<p class="matrx-print-block matrx-print-notice" style="border:1px dashed #94a3b8;border-radius:6px;padding:10px 12px;color:#475569;font-style:italic">${escapeHtml(
    output.notice
  )}</p>`;
}
function withMathStyles(htmlDocument) {
  if (!htmlDocument.includes('class="katex"') || htmlDocument.includes(KATEX_CSS_MARKER)) {
    return htmlDocument;
  }
  const style = `<style data-matrx-katex>${KATEX_CSS}</style>`;
  const head = htmlDocument.search(/<\/head>/i);
  return head >= 0 ? htmlDocument.slice(0, head) + style + htmlDocument.slice(head) : style + htmlDocument;
}
function openPrintWindow(rawDocument, filename = "print", windowFeatures = "width=920,height=720,scrollbars=yes") {
  const htmlDocument = withMathStyles(rawDocument);
  const win = window.open("", "_blank", windowFeatures);
  if (!win) return openPrintWindowFallback(htmlDocument, filename);
  win.document.open();
  win.document.write(htmlDocument);
  win.document.close();
  return "opened";
}
function openPendingPrintWindow(filename = "print", windowFeatures = "width=920,height=720,scrollbars=yes") {
  const win = window.open("", "_blank", windowFeatures);
  if (win) {
    win.document.open();
    win.document.write(
      '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Preparing\u2026</title></head><body style="font:14px -apple-system,BlinkMacSystemFont,sans-serif;color:#555;padding:2rem">Preparing the document for print\u2026</body></html>'
    );
    win.document.close();
  }
  return {
    write(rawDocument) {
      const htmlDocument = withMathStyles(rawDocument);
      if (!win || win.closed) return openPrintWindowFallback(htmlDocument, filename);
      win.document.open();
      win.document.write(htmlDocument);
      win.document.close();
      return "opened";
    }
  };
}
function openPrintWindowFallback(htmlDocument, filename) {
  downloadFile(`${filename.replace(/\s+/g, "-").toLowerCase()}.html`, htmlDocument, "text/html;charset=utf-8");
  return "downloaded";
}
